const ISSUE_ITEM_NAMES=['Bedsheet','Blanket','Quilt','Razai','Pillow','Pillow Cover','Mattress Protector','Towel'] as const;
function ResidentItemsPanel({data,currentProperty,save,busy}:{data:AppData;currentProperty:string;save:(body:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){
 const [residentId,setResidentId]=useState('');const [issueDate,setIssueDate]=useState(()=>new Date().toISOString().slice(0,10));const [condition,setCondition]=useState<'New'|'Previous'>('New');const [utensilsDescription,setUtensilsDescription]=useState('');const [items,setItems]=useState<Record<string,number>>(()=>Object.fromEntries(ISSUE_ITEM_NAMES.map(name=>[name,0])));
 const selectableResidents=data.residents.filter(r=>r.occupancyStatus!=='Exited'&&(currentProperty==='All properties'||r.property===currentProperty));const selected=selectableResidents.find(r=>r.id===residentId);const rawRoom=String(selected?.room||'').trim();const bed=rawRoom.match(/(?:·|\||,|-\s*)\s*Bed\s+([^·|,]+)/i)?.[1]?.trim()||'';const room=rawRoom.replace(/^Room\s+/i,'').replace(/\s*(?:·|\||,|-\s*)\s*Bed\s+[^·|,]+/i,'').trim();const visibleIssues=data.residentItemIssues.filter(issue=>currentProperty==='All properties'||issue.property===currentProperty);
 const submit=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!residentId)return;const ok=await save({residentId,issueDate,condition,items,utensilsDescription});if(ok){setItems(Object.fromEntries(ISSUE_ITEM_NAMES.map(name=>[name,0])));setUtensilsDescription('');setIssueDate(new Date().toISOString().slice(0,10));}};
 return <div className="resident-items-module"><form className="card issue-form-card" id="resident-item-issue-form" onSubmit={submit}><div className="card-heading"><div><span className="section-kicker">RESIDENT INVENTORY</span><h2>Issue items to a resident</h2><p>Select a current resident and record the items handed over.</p></div><span className="issue-condition-note"><ShieldCheck size={16}/> Saved to resident records</span></div><div className="issue-form-grid"><label className="issue-resident-field">Resident Name <b>*</b><select value={residentId} onChange={e=>setResidentId(e.target.value)} required><option value="">Select resident</option>{selectableResidents.map(r=><option key={r.id||r.name} value={r.id}>{r.name} · {r.property} · {r.room||'Room not assigned'}</option>)}</select></label><label>Issue Date <b>*</b><input type="date" value={issueDate} onChange={e=>setIssueDate(e.target.value)} required/></label><div className="issue-location-field"><span>Property</span><strong>{selected?.property||'Select a resident'}</strong></div><div className="issue-location-field"><span>Room</span><strong>{selected?(room||'Not assigned'):'—'}</strong></div><div className="issue-location-field"><span>Bed</span><strong>{selected?(bed||'Not specified'):'—'}</strong></div></div><div className="issue-section-heading"><div><strong>Items</strong><span>Enter the quantity of each item issued.</span></div><small>QUANTITY</small></div><div className="issue-item-grid">{ISSUE_ITEM_NAMES.map(name=><label className="issue-item-field" key={name}><span>{name}</span><input type="number" min="0" max="999" step="1" value={items[name]} onChange={e=>setItems(prev=>({...prev,[name]:Math.max(0,Math.min(999,Number(e.target.value)||0))}))} aria-label={`${name} quantity`}/></label>)}</div><label className="issue-utensils-field">Utensils (Description)<textarea value={utensilsDescription} onChange={e=>setUtensilsDescription(e.target.value)} placeholder="e.g., 2 Plates, 1 Glass, 1 Spoon..." rows={3}/></label><div className="issue-bottom-row"><fieldset className="issue-condition-field"><legend>Condition at issue <b>*</b></legend><div><label className={condition==='New'?'selected':''}><input type="radio" name="itemCondition" value="New" checked={condition==='New'} onChange={()=>setCondition('New')}/>New</label><label className={condition==='Previous'?'selected':''}><input type="radio" name="itemCondition" value="Previous" checked={condition==='Previous'} onChange={()=>setCondition('Previous')}/>Previous</label></div></fieldset><button type="submit" className="button button-primary issue-submit" disabled={busy||!selected}><Plus size={15}/>{busy?'Saving…':'Issue items'}</button></div></form><section className="card issue-history-card"><div className="card-heading"><div><span className="section-kicker">ISSUE REGISTER</span><h2>Recently issued items</h2><p>{visibleIssues.length} recorded issue{visibleIssues.length===1?'':'s'}{currentProperty!=='All properties'?` at ${currentProperty}`:''}.</p></div></div>{visibleIssues.length?<div className="issue-history-list">{visibleIssues.map(issue=>{const quantities=Object.entries(issue.items||{}).filter(([,count])=>Number(count)>0);const total=quantities.reduce((sum,[,count])=>sum+Number(count),0);return <article className="issue-history-row" key={issue.id}><div className="issue-history-date">{formatDateDMY(issue.issueDate)}</div><div className="issue-history-person"><strong>{issue.residentName}</strong><span>{issue.property} · Room {issue.room||'—'}{issue.bed?` · Bed ${issue.bed}`:''}</span></div><div className="issue-history-items">{quantities.map(([name,count])=><span key={name}>{name} × {count}</span>)}{issue.utensilsDescription&&<span>Utensils: {issue.utensilsDescription}</span>}</div><span className={`issue-condition-badge ${issue.condition.toLowerCase()}`}>{issue.condition}</span><strong className="issue-history-total">{total+(issue.utensilsDescription?1:0)} item{total+(issue.utensilsDescription?1:0)===1?'':'s'}</strong></article>})}</div>:<div className="issue-empty-state"><div><BedDouble size={20}/></div><strong>No issue records yet</strong><span>Items you issue will appear here.</span></div>}</section></div>;
}
