 const addLabel:Record<Page,string>={'Properties':'Add property','Residents':'Add resident','Bookings':'New enquiry','Public Listing':'Manage listings','Booking Leads':'View enquiries','Marketplace':'Browse marketplace','Rooms & beds':'Add room','Rent & payments':'Record payment','Electricity':'Add meter reading','Expenses':'Add expense','Maintenance':'New request','Staff':'Add staff','Assets':'Add asset','Resident items':'New issue','Reports':'Export report','Messages':'New message','Backup':'Backup now','Settings':'Save changes','Community Only':'Open community','Overview':'Add'};
